//! Regenerate the standalone token API's Unicode data with
//! `cargo run -p flux-proc-macro --example unicode_tables -- crates/flux-proc-macro/src/unicode_data.rs`.
use std::collections::BTreeMap;
use std::fmt::Write;

fn main() {
    let mut output = String::from(
        "// Generated by examples/unicode_tables.rs. Do not edit.\n// Unicode data from unicode-ident 1.0.27 and unicode-normalization 0.1.25.\n\n",
    );
    for (name, predicate) in [
        ("XID_START", unicode_ident::is_xid_start as fn(char) -> bool),
        ("XID_CONTINUE", unicode_ident::is_xid_continue),
    ] {
        writeln!(
            output,
            "#[rustfmt::skip]\npub(super) const {name}: &[(u32, u32)] = &["
        )
        .unwrap();
        let mut start = None;
        for n in 0..=0x110000 {
            if char::from_u32(n).is_some_and(predicate) {
                start.get_or_insert(n);
            } else if let Some(start) = start.take() {
                writeln!(output, "    (0x{start:X}, 0x{:X}),", n - 1).unwrap();
            }
        }
        output.push_str("];\n\n");
    }
    let mut decompositions = Vec::new();
    let mut compositions = BTreeMap::new();
    let mut classes = Vec::new();
    for ch in (0..=0x10ffff).filter_map(char::from_u32) {
        let class = unicode_normalization::char::canonical_combining_class(ch);
        if class != 0 {
            classes.push((ch as u32, class));
        }
        // Hangul is represented algorithmically in unicode.rs.
        if ('\u{AC00}'..='\u{D7A3}').contains(&ch) {
            continue;
        }
        let mut decomposition = Vec::new();
        unicode_normalization::char::decompose_canonical(ch, |c| decomposition.push(c));
        if decomposition != [ch] {
            let mut starter = decomposition[0];
            for &next in &decomposition[1..] {
                if let Some(composed) = unicode_normalization::char::compose(starter, next) {
                    compositions.insert((starter as u32, next as u32), composed as u32);
                    starter = composed;
                } else if unicode_normalization::char::canonical_combining_class(next) == 0 {
                    starter = next;
                }
            }
            decompositions.push((ch as u32, decomposition));
        }
    }
    output.push_str("#[rustfmt::skip]\npub(super) const CLASSES: &[(u32, u8)] = &[\n");
    for (ch, class) in classes {
        writeln!(output, "    (0x{ch:X}, {class}),").unwrap();
    }
    output.push_str(
        "];\n\n#[rustfmt::skip]\npub(super) const DECOMPOSITIONS: &[(u32, &[char])] = &[\n",
    );
    for (ch, decomposition) in decompositions {
        write!(output, "    (0x{ch:X}, &[").unwrap();
        for c in decomposition {
            write!(output, "'\\u{{{:X}}}',", c as u32).unwrap();
        }
        output.push_str("]),\n");
    }
    output.push_str(
        "];\n\n#[rustfmt::skip]\npub(super) const COMPOSITIONS: &[((u32, u32), char)] = &[\n",
    );
    for ((a, b), ch) in compositions {
        writeln!(output, "    ((0x{a:X}, 0x{b:X}), '\\u{{{ch:X}}}'),").unwrap();
    }
    output.push_str("];\n");
    if let Some(path) = std::env::args_os().nth(1) {
        std::fs::write(path, output).unwrap();
    } else {
        print!("{output}");
    }
}
